@FunctionalInterface interface CheckedRunnable { void run() throws IOException; }
static void mute(CheckedRunnable r) {
  try { r.run(); } catch (IOException ignored) {
    LOG.debug("muted", ignored);   // keep a breadcrumb; never swallow silently
  }
}
